class SentenceCountMetric(BaseMetric):
    def __init__(self, min_sentences: int = {{min_sentences}}, max_sentences: int = {{max_sentences}}, threshold: float = {{threshold}}):
        self.threshold = threshold
        self.min_sentences = min_sentences
        self.max_sentences = max_sentences
        self.evaluation_model = "sentence-counter"

    def measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        actual = (test_case.actual_output or "").strip()
        sentences = [s.strip() for s in actual.replace("!", ".").replace("?", ".").replace("。", ".").split(".") if s.strip()]
        count = len(sentences)
        if self.min_sentences <= count <= self.max_sentences:
            self.score = 1.0
            self.reason = f"句子数 {count} 在 [{self.min_sentences}, {self.max_sentences}] 范围内"
        elif count < self.min_sentences:
            self.score = round(count / self.min_sentences, 2)
            self.reason = f"句子数 {count} 少于下限 {self.min_sentences}"
        else:
            self.score = round(self.max_sentences / count, 2)
            self.reason = f"句子数 {count} 超过上限 {self.max_sentences}"
        self.success = self.score >= self.threshold
        return self.score

    async def a_measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        return self.measure(test_case)

    def is_successful(self) -> bool:
        return bool(self.score and self.score >= self.threshold)

    @property
    def __name__(self):
        return "Sentence Count"
